<body>
  <main class="page">
    <section class="card" aria-labelledby="support-title">
      <p class="eyebrow">Support</p>
      <h1 id="support-title">Contact our team</h1>
      <p class="subtitle">Send us a note and we&apos;ll get back to you as soon as we can.</p>

      <form id="contact-form" novalidate>
        <div class="form-field" id="name-field">
          <label for="full-name">Full name</label>
          <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="name-error">
          <div class="error-message" id="name-error" aria-live="polite"></div>
        </div>

        <div class="form-field" id="email-field">
          <label for="email-address">Email address</label>
          <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-error">
          <div class="error-message" id="email-error" aria-live="polite"></div>
        </div>

        <div class="form-field" id="phone-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phoneNumber"
            type="tel"
            inputmode="tel"
            autocomplete="tel"
            placeholder="(555) 123-4567"
            aria-describedby="phone-hint phone-error"
          >
          <p class="field-hint" id="phone-hint">Optional. Use a format like (555) 123-4567 or 555-123-4567.</p>
          <div class="error-message" id="phone-error" aria-live="polite"></div>
        </div>

        <div class="actions">
          <button type="submit">Send message</button>
        </div>

        <p class="form-status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('contact-form');
    const fields = {
      name: {
        input: document.getElementById('full-name'),
        wrapper: document.getElementById('name-field'),
        error: document.getElementById('name-error')
      },
      email: {
        input: document.getElementById('email-address'),
        wrapper: document.getElementById('email-field'),
        error: document.getElementById('email-error')
      },
      phone: {
        input: document.getElementById('phone-number'),
        wrapper: document.getElementById('phone-field'),
        error: document.getElementById('phone-error')
      }
    };
    const status = document.getElementById('form-status');

    function setFieldState(field, message) {
      field.wrapper.classList.toggle('invalid', Boolean(message));
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
      field.error.textContent = message || '';
    }

    function validateName() {
      const value = fields.name.input.value.trim();
      if (!value) {
        setFieldState(fields.name, 'Full name is required.');
        return false;
      }
      setFieldState(fields.name, '');
      return true;
    }

    function validateEmail() {
      const value = fields.email.input.value.trim();
      if (!value) {
        setFieldState(fields.email, 'Email address is required.');
        return false;
      }
      if (!fields.email.input.checkValidity()) {
        setFieldState(fields.email, 'Enter a valid email address.');
        return false;
      }
      setFieldState(fields.email, '');
      return true;
    }

    function validatePhone() {
      const value = fields.phone.input.value.trim();
      if (!value) {
        setFieldState(fields.phone, '');
        return true;
      }

      const compactValue = value.replace(/[()\s-]/g, '');
      const allowedPattern = /^(\+?\d{1,3})?\d{10}$/;
      const displayPattern = /^(\+?\d{1,3}[\s-]?)?(\(?\d{3}\)?[\s-]?)\d{3}[\s-]?\d{4}$/;

      if (!allowedPattern.test(compactValue) && !displayPattern.test(value)) {
        setFieldState(fields.phone, 'Enter a valid phone number.');
        return false;
      }

      setFieldState(fields.phone, '');
      return true;
    }

    function validateForm() {
      const nameValid = validateName();
      const emailValid = validateEmail();
      const phoneValid = validatePhone();
      return nameValid && emailValid && phoneValid;
    }

    fields.name.input.addEventListener('blur', validateName);
    fields.email.input.addEventListener('blur', validateEmail);
    fields.phone.input.addEventListener('blur', validatePhone);

    fields.name.input.addEventListener('input', () => {
      if (fields.name.wrapper.classList.contains('invalid')) validateName();
    });
    fields.email.input.addEventListener('input', () => {
      if (fields.email.wrapper.classList.contains('invalid')) validateEmail();
    });
    fields.phone.input.addEventListener('input', () => {
      if (fields.phone.wrapper.classList.contains('invalid')) validatePhone();
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      if (validateForm()) {
        status.textContent = 'Thanks — your message is ready to send.';
        form.reset();
        Object.values(fields).forEach((field) => setFieldState(field, ''));
      }
    });
  </script>
</body>
</html>
